INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(14001, 'Psalms 71:13', 'Psalms', 71, 13, '&nbsp;څوک چې ما پورې تور تړى نو و دې شرميږى او تباه دې شى، څوک چې ما ته نقصان رسول غواړى، هغوئ دې سپک شى او په شرمونو کښې دې پټ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14002, 'Psalms 71:14', 'Psalms', 71, 14, '&nbsp;خو زۀ به همېشه دپاره ستا نه اُميد کوم، زۀ به ستا ثناء صِفت ډېر ډېر کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14003, 'Psalms 71:15', 'Psalms', 71, 15, '&nbsp;زۀ به په خپله ستا صداقت بيان کړم، ټوله ورځ به ستا خلاصون بيانوم، کۀ څۀ هم زۀ په وينا کښې ماهر نۀ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14004, 'Psalms 71:16', 'Psalms', 71, 16, '&nbsp;اے قادر مطلق مالِک خُدايه زۀ به ستا د لويئ کارونه بيان کړم. چې صرف تۀ اِنصاف کوونکے يې زۀ به هر چا ته ووايم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14005, 'Psalms 71:17', 'Psalms', 71, 17, '&nbsp;د ورکوټوالى نه دې ما له تعليم راکړے دے اے پاکه خُدايه، زۀ تر ننه پورې ستا عجيبه کارونه ستايم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14006, 'Psalms 71:18', 'Psalms', 71, 18, '&nbsp;کۀ چرې زۀ هم بوډا او سپين‌ږيرے شم، خو اے پاکه خُدايه، ما مۀ پرېږده ځان له، ترڅو چې زۀ راتلونکى نسل ته ستا قدرت بيان نۀ کړم، او ټولو را روانو نسلونو ته ستا زور بيان نۀ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14007, 'Psalms 71:19', 'Psalms', 71, 19, '&nbsp;ستا صداقت آسمانونو ته رسيږى پاکه خُدايه، هم دا تا کړې دى لوئ کارونه. ستا په شان بل څوک نشته پاکه خُدايه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14008, 'Psalms 71:20', 'Psalms', 71, 20, '&nbsp;کۀ څۀ هم تا زۀ د ډېرو سختو سره مخ کړم، تۀ به دوباره ما ژوندے کړې، او د زمکې د ژورې کندې نه به مې راوباسې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14009, 'Psalms 71:21', 'Psalms', 71, 21, '&nbsp;تۀ به زما عزت زيات کړې، يو ځل بيا به ډاډګيرنه راکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14010, 'Psalms 71:22', 'Psalms', 71, 22, '&nbsp;زۀ به ستا ثناء صِفت د سريندې په ساز کښې کوم، ځکه چې تۀ په خپلو وعدو وفادار يې، زۀ به د رباب په نغمو کښې ستا صِفت کوم، اے د بنى اِسرائيلو مقدس خُدايه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14011, 'Psalms 71:23', 'Psalms', 71, 23, '&nbsp;زما شونډې به د خوشحالۍ وکړى آوازونه، کله چې زۀ ستا ثناء صِفت کومه، ځکه چې تا زۀ بچ کړے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14012, 'Psalms 71:24', 'Psalms', 71, 24, '&nbsp;زما ژبه به ستا صداقت ټوله ورځ بيانوى، ځکه چا چې غوښتل چې ما ته نقصان ورسوى هغوئ به په شرم او په بې‌عزتۍ اخته وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14013, 'Psalms 72:1', 'Psalms', 72, 1, '&nbsp;اے خُدايه پاکه، د اِنصاف دپاره بادشاه له همت ورکړه، او د بادشاه زوئ له صداقت ورکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14014, 'Psalms 72:2', 'Psalms', 72, 2, '&nbsp;هغه به په صداقت سره د خلقو عدالت وکړى، ستا د مظلومانو به په اِنصاف سره عدالت وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14015, 'Psalms 72:3', 'Psalms', 72, 3, '&nbsp;غرونه به خلقو ته آبادى راولى، غونډۍ دې د صداقت مېوه ونيسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14016, 'Psalms 72:4', 'Psalms', 72, 4, '&nbsp;او هغه به د خلقو په مينځ کښې د مظلومانو مدد وکړى، او د غريبانانو بچو ته به خلاصون ورکړى، او ظالمان به د پښو لاندې کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14017, 'Psalms 72:5', 'Psalms', 72, 5, '&nbsp;ترڅو چې په آسمان کښې نمر او سپوږمۍ وى، ټول خلق به تا نه يريږى، نسل در نسل به دا جارى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14018, 'Psalms 72:6', 'Psalms', 72, 6, '&nbsp;نو بادشاه دې د باران په شان د واښو په پټو راوريږى، لکه د باران په څاڅکو چې زمکه سيرابيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14019, 'Psalms 72:7', 'Psalms', 72, 7, '&nbsp;د هغۀ په ورځو کښې به صادقان آباد وى، ترڅو چې په آسمان کښې سپوږمۍ وى نو تر هغه وخته به آباد وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14020, 'Psalms 72:8', 'Psalms', 72, 8, '&nbsp;هغه به د سمندر نه تر سمندر پورې، او د فرات د سيند نه د زمکې تر آخره به حکومت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14021, 'Psalms 72:9', 'Psalms', 72, 9, '&nbsp;د دشتو کوچيان به د هغۀ په وړاندې په سجده شى، د هغۀ دشمنان به خاورى په خولۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14022, 'Psalms 72:10', 'Psalms', 72, 10, '&nbsp;هغۀ ته به د ترسيس بادشاهان او د لرو لرو جزيرو نه قلنګ راوړى، هغۀ ته به د شيبا او سِيبا بادشاهان تحفې راوړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14023, 'Psalms 72:11', 'Psalms', 72, 11, '&nbsp;ټول بادشاهان به هغۀ ته په سجده شى، ټول قومونه به د هغۀ خِدمت ګزار شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14024, 'Psalms 72:12', 'Psalms', 72, 12, '&nbsp;هغه به حاجتمندو له خلاصون ورکړى څوک چې هغۀ ته وژاړى، او د هغه مظلومانو به مددګار وى د چا چې څوک نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14025, 'Psalms 72:13', 'Psalms', 72, 13, '&nbsp;په ضعيفانو او په حاجتمندانو به رحم وکړى، او حاجتمندان به د مرګ نه بچ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14026, 'Psalms 72:14', 'Psalms', 72, 14, '&nbsp;هغه به دوئ د ظلم او جبر نه بچ کړى، د هغۀ په نظر کښې د دوئ وينه ده ډېره قيمتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14027, 'Psalms 72:15', 'Psalms', 72, 15, '&nbsp;د بادشاه عمر دې ډېر شى د شيبا سرۀ زر دې هغۀ ته ورکړے شى، خلق دې تل د هغۀ دپاره دُعا وغواړى، او ټوله ورځ دې هغۀ ته د خُدائ پاک برکت ورکړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14028, 'Psalms 72:16', 'Psalms', 72, 16, '&nbsp;غله دانه دې په مُلک کښې ډېره تېره شى، تر دې چې د غرونو په سرونو دې غلې دانې وشى. د لبنان د مېوو په شان دې مېوه زياته شى، لکه څنګه چې پټى د واښو نه شنۀ دى، دغه شان دې انسانان په کښې ډېر شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14029, 'Psalms 72:17', 'Psalms', 72, 17, '&nbsp;د بادشاه نوم دې د تل دپاره پاتې شى، ترڅو چې نمر وى تر هغې دې پاتې شى. ټول قومونه دې د هغۀ په وسيله برکتى شى، او هغوئ دې ورته بختور ووائى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14030, 'Psalms 72:18', 'Psalms', 72, 18, '&nbsp;ثناء صِفت دې مالِک خُدائ، د بنى اِسرائيلو خُدائ پاک ته وى، څوک چې په يواځې ځان په خپله عجيبه کارونه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14031, 'Psalms 72:19', 'Psalms', 72, 19, '&nbsp;د هغۀ جلالى نوم ته دې د تل دپاره ثناء صِفت وى، ټوله زمکه دې د هغۀ د جلال نه ډکه وى. آمين ثُمه آمين.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14032, 'Psalms 72:20', 'Psalms', 72, 20, '&nbsp;دا د داؤد د دُعاګانو خاتمه ده، څوک چې د يَسى زوئ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14033, 'Psalms 73:1', 'Psalms', 73, 1, '&nbsp;خُدائ پاک بې‌شکه د بنى اِسرائيلو سره ښۀ دے، او د چا زړونه چې صفا وى د هغوئ سره ښۀ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14034, 'Psalms 73:2', 'Psalms', 73, 2, '&nbsp;خو څومره چې زما په متعلق خبره وه تقريباً پښې مې ښوئېدو ته نزدې شوې وې، نزدې وه چې زمکه مې د پښو نه تښتېدلے وے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14035, 'Psalms 73:3', 'Psalms', 73, 3, '&nbsp;نو ما د کبرژنو سره کينه وکړه، هرکله چې ما د بدکارانو ترقى وليده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14036, 'Psalms 73:4', 'Psalms', 73, 4, '&nbsp;هغوئ هيڅ قسمه تکليف نۀ لرى، او د هغوئ وجود صحتمند او قوى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14037, 'Psalms 73:5', 'Psalms', 73, 5, '&nbsp;او د نورو خلقو غوندې هغوئ په تکليف کښې نۀ دى، او د نورو خلقو غوندې په سختو او کړاونو کښې نۀ دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14038, 'Psalms 73:6', 'Psalms', 73, 6, '&nbsp;ځکه د دوئ غاړه د فخر اميل دے، او دوئ د شرارت جامې اغوستې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14039, 'Psalms 73:7', 'Psalms', 73, 7, '&nbsp;د مال دولت په وجه هغوئ غټ سترګى دى، د دوئ د ذهنونو د ګنده خيالاتو څۀ حد نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14040, 'Psalms 73:8', 'Psalms', 73, 8, '&nbsp;د خلقو بې‌عزتى کوى او د نفرت او حسد نه ډکې خبرې کوى، په کبرژنه لهجه په خپله ژبه سره د ظلم او زياتې خبرې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14041, 'Psalms 73:9', 'Psalms', 73, 9, '&nbsp;د هغوئ خبرې د آسمان نه هم اوچتې دى، او په خپله ژبه يې ټوله دُنيا وخوړله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14042, 'Psalms 73:10', 'Psalms', 73, 10, '&nbsp;نو په دې وجه د خُدائ پاک د غوره شوو خلقو هم دوئ ته پام شو، او د هغوئ خبرو منلو ته ليواله شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14043, 'Psalms 73:11', 'Psalms', 73, 11, '&nbsp;دوئ وائى چې، ”خُدائ پاک ته به پته لګى څۀ؟ خُدائ تعالىٰ سره داسې عِلم شته دے څۀ؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14044, 'Psalms 73:12', 'Psalms', 73, 12, '&nbsp;دا بدکاران وګورئ دغه شان وى، چې ژوند يې په آرام وى مال دولت يې زياتيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14045, 'Psalms 73:13', 'Psalms', 73, 13, '&nbsp;نو بيا ما هسې خپل زړۀ پاک ساتلے دے، او ځان مې هسې د ګناه نه بچ ساتلے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14046, 'Psalms 73:14', 'Psalms', 73, 14, '&nbsp;زۀ به ټوله ورځ کړېدلم، هر سحر به وهلے کېدلم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14047, 'Psalms 73:15', 'Psalms', 73, 15, '&nbsp;کۀ چرې ما داسې وئيلے، نو ما به ستا د بچو هم شېطانت کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14048, 'Psalms 73:16', 'Psalms', 73, 16, '&nbsp;کله چې ما پرې د پوهېدو کوشش وکړو، نو دا کار ما ته سخت ښکاره شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14049, 'Psalms 73:17', 'Psalms', 73, 17, '&nbsp;ترڅو چې زۀ د خُدائ پاک مقدس ځائ ته ورننوتم، نو بيا زۀ د بدکارانو د اَنجام نه خبر شوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14050, 'Psalms 73:18', 'Psalms', 73, 18, '&nbsp;تا بې‌شکه چې هغوئ په ښوئېدونکې زمکه ودرولى دى، هغوئ تا د بربادۍ کندې ته ښکته غورزولى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14051, 'Psalms 73:19', 'Psalms', 73, 19, '&nbsp;ناګهانه به هغوئ برباد شى، دوئ به په يره او وحشت کښې راګېر شى او په پوره طور سره به فنا شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14052, 'Psalms 73:20', 'Psalms', 73, 20, '&nbsp;لکه څنګه چې څوک د خوب نه راپاڅى او خوب ليدل يې ختم شى. نو هغوئ به هم ختم شى کله چې تۀ مالِکه خُدايه راپاڅې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14053, 'Psalms 73:21', 'Psalms', 73, 21, '&nbsp;نو کله چې زما زړۀ خفه وو، او روح زما په ما کښې زخمى شوے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14054, 'Psalms 73:22', 'Psalms', 73, 22, '&nbsp;زۀ څومره بې‌احساسه او جټ جاهله وم، زۀ به تا ته د بې‌عقله ځناور په شان ښکاره کېدم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14055, 'Psalms 73:23', 'Psalms', 73, 23, '&nbsp;خو د هر څۀ باوجود به بيا هم زۀ د تل دپاره تا سره يم، په خپله مې د ښى لاس نه راونيسه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14056, 'Psalms 73:24', 'Psalms', 73, 24, '&nbsp;د خپلې مشورې په ذريعه زما رهنمائى کوې، نو آخر به هم ما خپل جلال ته راوغواړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14057, 'Psalms 73:25', 'Psalms', 73, 25, '&nbsp;په آسمان کښې زما څوک دى بې له تا نه؟ د بل چا خواهش نۀ لرم په زمکه غېر ستا نه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14058, 'Psalms 73:26', 'Psalms', 73, 26, '&nbsp;کۀ هر څومره زما زړۀ او بدن کمزورى وى، خو د تل دپاره به خُدائ زما د زړۀ زور او اُميد وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14059, 'Psalms 73:27', 'Psalms', 73, 27, '&nbsp;څوک چې تا نه لرې دى هغوئ به تباه شى، او هغوئ چې تا سره وفادار نۀ وى نو تباه به شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14060, 'Psalms 73:28', 'Psalms', 73, 28, '&nbsp;خو زما دپاره به دا ښۀ وى چې زۀ خُدائ ته نزدې شم. ما تۀ خپله پناه ګاه جوړه کړې قادر مطلق مالِکه خُدايه، زۀ به ستا ټول کارونه بيانوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14061, 'Psalms 74:1', 'Psalms', 74, 1, '&nbsp;اے خُدايه پاکه، ولې، تا مونږ د تل دپاره رد کړى يُو څۀ؟ ولې ستا غصه به د خپلې رمې په ګډو باندې وى څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14062, 'Psalms 74:2', 'Psalms', 74, 2, '&nbsp;هغه خلق راپه ياد کړه چې د پخوا نه تا په بيعه اخستى دى، او د هغه قوم فديه دې ورکړې ده کوم چې ستا ميراث دے، د صيون غر راپه ياد کړه کوم ځائ چې تۀ اوسېدلے يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14063, 'Psalms 74:3', 'Psalms', 74, 3, '&nbsp;د هغوئ په دائمى کنډرو کښې خپل قدم کېږده، ځکه چې دشمن ستا په عبادتخانه کښې هر څۀ تباه کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14064, 'Psalms 74:4', 'Psalms', 74, 4, '&nbsp;ستا په عبادتګاه کښې ستا دشمنانو چغې وهلې دى، او دوئ هلته خپلې د فتحې جنډې لګولې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14065, 'Psalms 74:5', 'Psalms', 74, 5, '&nbsp;دوئ د هغه کسانو په شان ښکارى چا چې خپل تبرُونه اوچت کړى وى چې په هغوئ د ټولو نه غټې ونې راوغورزوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14066, 'Psalms 74:6', 'Psalms', 74, 6, '&nbsp;هغوئ ستا د عبادتګاه ټولې د ګُلکارۍ تختې په خپلو تبرُونو او ترښځو سره ورانې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14067, 'Psalms 74:7', 'Psalms', 74, 7, '&nbsp;ستا پاک ځائ ته يې اور واچولو او ختم يې کړو، او ستا د نوم د اوسېدلو ځائ يې سپک او بې‌حرمته کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14068, 'Psalms 74:8', 'Psalms', 74, 8, '&nbsp;او هغوئ په خپلو زړونو کښې وائى چې، ”مونږ به دوئ بلکل چخڼى کړُو.“ دوئ هغه ټول ځايونه وسوزول کوم ځائ به چې د خُدائ پاک عبادت کېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14069, 'Psalms 74:9', 'Psalms', 74, 9, '&nbsp;مونږ نۀ معجزه وليده او نۀ راسره پېغمبر پاتې شو، او په مونږ کښې هيڅ څوک په دې نۀ پوهېدو چې دا حالت به کله ختم شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14070, 'Psalms 74:10', 'Psalms', 74, 10, '&nbsp;اے پاکه خُدايه، ترڅو به دشمن ستا نوم پورې خندا کوى؟ او تل به هغه ستا د نوم بې‌حرمتى کوى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14071, 'Psalms 74:11', 'Psalms', 74, 11, '&nbsp;تا ولې خپل زورَور ښے لاس استعمال نۀ کړو؟ نو خپل لاس او قدرت دې راڅرګند کړه او دوئ برباد کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14072, 'Psalms 74:12', 'Psalms', 74, 12, '&nbsp;خو پاکه خُدايه د ازله تۀ يې بادشاه زما، زمکې له راوړے خلاصون دے تا.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14073, 'Psalms 74:13', 'Psalms', 74, 13, '&nbsp;تا په خپل قدرت سره سمندر په مينځ جدا کړو، د غټو بلاګانو سرونه دې په سمندر کښې مات کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14074, 'Psalms 74:14', 'Psalms', 74, 14, '&nbsp;تا د سمندرى بلاګانو سرونه مات کړل، او د صحراګانو په ځناورو دې د دوئ غوښې وخوړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14075, 'Psalms 74:15', 'Psalms', 74, 15, '&nbsp;تا زمونږ دپاره چينې او نِهرونه پرانستل، او تل بهېدونکى دريابونه دې وُچ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14076, 'Psalms 74:16', 'Psalms', 74, 16, '&nbsp;ورځې دى کۀ شپې دى دواړه ستا دى، نمر او سپوږمۍ تا په خپل ځائ مقرر کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14077, 'Psalms 74:17', 'Psalms', 74, 17, '&nbsp;تا په خپله د زمکې ټول سرحدونه مقرر کړل، تا دواړه د ګرمۍ او يخنۍ موسمونه پېدا کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14078, 'Psalms 74:18', 'Psalms', 74, 18, '&nbsp;مالِکه خُدايه راياد کړه چې دشمن به څنګه تا پورې ټوقې کولې، او څنګه به کم عقلانو ستا د نوم ګستاخى کوله،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14079, 'Psalms 74:19', 'Psalms', 74, 19, '&nbsp;د خپلې ګوګوشتکې ژوند ځناورو ته مۀ حواله کوه او د خپلو مظلومانو ژوند د تل دپاره مۀ هېروه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14080, 'Psalms 74:20', 'Psalms', 74, 20, '&nbsp;د خپل لوظ احترام کوه، ځکه چې د زمکې ټول تيارۀ ځايونه د ظلم نه ډک دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14081, 'Psalms 74:21', 'Psalms', 74, 21, '&nbsp;مظلومان مۀ پرېږده چې دوباره شرمنده شى، مسکينان او غريبانان دې ستا د نوم ثنا خوان شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14082, 'Psalms 74:22', 'Psalms', 74, 22, '&nbsp;راپاڅه، پاکه خُدايه، او د خپلې دعوې دفاع وکړه، راپه ياد کړه چې څومره بې‌وقوفانو هر وخت ستا د نوم ګستاخى کوله،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14083, 'Psalms 74:23', 'Psalms', 74, 23, '&nbsp;د خپلو مخالفو نعرې ياد ساته، د خپلو دشمنانو شور چې هر وخت چغې وهى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14084, 'Psalms 75:1', 'Psalms', 75, 1, '&nbsp;مونږ پاکه خُدايه ستا شُکر کوُو، مونږ شُکر کوُو چې ستا نوم نزدې دے، او خلق ستا د عجيبه کارونو په حقله خبرې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14085, 'Psalms 75:2', 'Psalms', 75, 2, '&nbsp;تا وفرمائيل چې، ”مقرر شوے وخت زۀ په خپله خپل ځان له خوښوم، دا زۀ يم چې دغه رنګ د اِنصاف فېصلې کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14086, 'Psalms 75:3', 'Psalms', 75, 3, '&nbsp;کله چې دُنيا او هر ژوندے څيز هم په کښې لړزيږى، خو دا زۀ يم چې د دې ستنې مې کلکې نيولى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14087, 'Psalms 75:4', 'Psalms', 75, 4, '&nbsp;مغرُورو ته وايمه چې لافې نۀ کوى، او بدکارانو ته وايمه چې په خپل قدرت فخر نۀ کوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14088, 'Psalms 75:5', 'Psalms', 75, 5, '&nbsp;خپل ښکرونه د آسمان خلاف مۀ اوچتوئ، او په هسکه غړۍ خبرې مۀ کوئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14089, 'Psalms 75:6', 'Psalms', 75, 6, '&nbsp;هيڅ څوک د مشرق نه تر مغربه پورې نشته، او نۀ په صحرا کښې څوک شته چې انسان اوچت کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14090, 'Psalms 75:7', 'Psalms', 75, 7, '&nbsp;خو دا خُدائ پاک دے څوک چې اِنصاف کوى، او هغه يو لاندې کوى او بل اوچتوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14091, 'Psalms 75:8', 'Psalms', 75, 8, '&nbsp;د مالِک خُدائ په لاس کښې پيالۍ ده، چې د هغۀ د غضب د ترخو ميو نه ډکه ده، هغه يې توئيوى چې د دُنيا ټول بدعمله خلق يې تر آخره پورې وڅښى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14092, 'Psalms 75:9', 'Psalms', 75, 9, '&nbsp;خو زۀ به يې تر ابده پورې ستايم، زۀ به په سندرو کښې د يعقوب د خُدائ پاک ثناء صِفت کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14093, 'Psalms 75:10', 'Psalms', 75, 10, '&nbsp;مالِک خُدائ فرمائى چې زۀ به د ټولو شريرانو ښکرونه مات کړم، خو د نېکانو ښکرونه به اوچت کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14094, 'Psalms 76:1', 'Psalms', 76, 1, '&nbsp;خُدائ پاک په يهوداه کښې مشهور دے، د هغۀ په بنى اِسرائيلو کښې لوئ نوم دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14095, 'Psalms 76:2', 'Psalms', 76, 2, '&nbsp;د هغۀ خېمه په شاليم کښې ده، او د هغۀ استوګنه په صيون کښې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14096, 'Psalms 76:3', 'Psalms', 76, 3, '&nbsp;هلته هغۀ د اور غشى مات کړل، ډالونه او تُورې او وسله يې د جنګ مات کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14097, 'Psalms 76:4', 'Psalms', 76, 4, '&nbsp;تۀ نُور او جلال لرې، د اوچتو غرونو نه زيات شان او شوکت لرې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14098, 'Psalms 76:5', 'Psalms', 76, 5, '&nbsp;د دشمنانو تکړه کسان هلته لوټ شول او په ابدى خوب اودۀ شول. يو جنګيالى بيا هم خپل لاسونه اوچتولے نۀ شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14099, 'Psalms 76:6', 'Psalms', 76, 6, '&nbsp;ستا په رټلو، اے د يعقوب پاکه خُدايه، آسونه او سورلى يې دواړه شول په خوب اودۀ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14100, 'Psalms 76:7', 'Psalms', 76, 7, '&nbsp;صرف ستا نه يرېدل په کار دى، کله چې تۀ په قهر يې څوک ستا په وړاندې ودرېدے شى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');